Given an array arr[] and a target value, the task is to find the count of quadruplets present in the given array having sum equal to the given target. Examples:Input: arr[] = [1, 5, 3, 1, 2, 10], target = 20Output: 1Explanation: Only quadruplet satisfying the conditions is arr[1] + arr[2] + arr[4] + arr[5] = 5 + 3 + 2 + 10 = 20.Input: arr[] = [1, 1, 1, 1, 1], target = 4Output: 5Explanation: arr[0] + arr[1] + arr[2] + arr[3]  = 4arr[0] + arr[1] + arr[3] + arr[4] = 4arr[0] + arr[1] + arr[2] + arr[4] = 4arr[0] + arr[2] + arr[3] + arr[4] = 4arr[1] + arr[2] + arr[3] + arr[4] = 4Input: arr = [4, 3, -13, 3], target = -3Output: 1Explanation: There is only 1 quadruplet with sum = -3, that is [4, 3, -13, 3].Try It YourselfTable of ContentNaive Approach - O(n^4) Time and O(1) SpaceBetter Approach - O(n^3) Time and O(n) SpaceEfficient Approach - O(n^2) Time and O(n^2) SpaceNaive Approach - O(n^4) Time and O(1) SpaceThe idea is to generate all possible combinations of length 4 from the given array. For each quadruplet, if the sum equals target, then increment the counter by 1. 
            C++

    #include <iostream>
#include <vector>
using namespace std;

// Function to return the number of quadruplets 
// with the given target sum
int countSum(vector<int>& arr, int target) {
    int n = arr.size(); 
    int count = 0;      

    // Loop over all possible quadruplets
    for (int i = 0; i < n - 3; i++) {
        for (int j = i + 1; j < n - 2; j++) {
            for (int k = j + 1; k < n - 1; k++) {
                for (int l = k + 1; l < n; l++) {                  
                    if (arr[i] + arr[j] + arr[k] + arr[l] == target) {
                        count++;
                    }
                }
            }
        }
    }

    return count; 
}

int main() {
    vector<int> arr = {1, 1, 1, 1, 1};
    int target = 4;
    cout << countSum(arr, target) << endl;
    return 0;
}


